#include <cstddef>
#include <cstdint>
#include <iostream>

struct Quote {            // one instrument's market state
    double bid;           // 8 bytes
    double ask;           // 8 bytes
    std::int32_t symId;   // 4 bytes
    bool stale;           // 1 byte
};                        // 8 + 8 + 4 + 1 = 21 -> padded to 24

int main() {
    std::cout << sizeof(Quote) << '\n';       // 24 (padded for 8-byte alignment)
    std::cout << 64 / sizeof(Quote) << '\n';  // 2  whole quotes per cache line
}
// Per 64-byte line: 48 bytes of struct, but only 32 bytes (bid+ask)
// are useful to the spread loop -> 50% cache-line utilisation.

#include <cstddef>
#include <cstdint>
#include <vector>

// Structure of arrays: each field is its own contiguous array.
struct QuoteBook {
    std::vector<double> bid;
    std::vector<double> ask;
    std::vector<std::int32_t> symId;
    std::vector<bool> stale;
};

// Hot path touches ONLY bid and ask; symId/stale bytes never enter the cache.
double totalSpread(const QuoteBook& b) {
    double s = 0.0;
    const std::size_t n = b.bid.size();
    for (std::size_t i = 0; i < n; ++i)
        s += b.ask[i] - b.bid[i];   // two perfectly sequential streams
    return s;
}
// A 64-byte line now holds 8 bids (or 8 asks), all useful -> 100% utilisation,
// and the prefetcher can stream both arrays ahead of the loop.

#include <new>   // std::hardware_destructive_interference_size (C++17)

struct alignas(64) ThreadCounters {   // one counter set per cache line
    std::uint64_t fills = 0;
    std::uint64_t rejects = 0;
    // padding to 64 bytes happens implicitly via alignas(64)
};
// Two threads writing counters[0].fills and counters[1].fills now touch
// different lines - no coherence traffic, no false sharing.

